content:
{
  "test_cases": [
    {
      "id": "TC-01",
      "title": "OBU initiates termination upon trackside order",
      "covers": [
        "ETC-012"
      ],
      "type": "Normal",
      "priority": "Yüksek",
      "preconditions": "An active communication session is established between the OBU and the trackside (RBC).",
      "test_inputs": "Trackside sends a 'Termination of Communication Session' order.",
      "assumptions": "",
      "steps": [
        {
          "no": 1,
          "action": "The trackside sends a termination order to the OBU.",
          "expected": "The OBU initiates the termination of the communication session."
        }
      ]
    },
    {
      "id": "TC-02",
      "title": "OBU does not initiate termination without trackside order or condition",
      "covers": [
        "ETC-012"
      ],
      "type": "Normal",
      "priority": "Orta",
      "preconditions": "An active communication session is established. No termination conditions from SUBSET-026 are fulfilled.",
      "test_inputs": "No trackside order is sent. No termination condition is triggered.",
      "assumptions": "",
      "steps": [
        {
          "no": 1,
          "action": "Wait for a duration longer than the fixed waiting time without any trackside order or termination condition.",
          "expected": "The OBU does not initiate the termination of the communication session."
        }
      ]
    },
    {
      "id": "TC-03",
      "title": "OBU repeats termination message if no acknowledgement is received",
      "covers": [
        "ETC-013"
      ],
      "type": "Normal",
      "priority": "Yüksek",
      "preconditions": "The OBU has initiated the termination of the communication session and sent the 'Termination of Communication Session' message.",
      "test_inputs": "No acknowledgement is received from the trackside within the fixed waiting time.",
      "assumptions": "The fixed waiting time is defined in SUBSET-026 Appendix A.3.1.",
      "steps": [
        {
          "no": 1,
          "action": "The OBU sends the 'Termination of Communication Session' message.",
          "expected": "The message is transmitted."
        },
        {
          "no": 2,
          "action": "Wait for the fixed waiting time without receiving an acknowledgement.",
          "expected": "The OBU repeats the 'Termination of Communication Session' message."
        }
      ]
    },
    {
      "id": "TC-04",
      "title": "OBU considers session terminated after maximum repetitions without acknowledgement",
      "covers": [
        "ETC-014"
      ],
      "type": "Sınır",
      "priority": "Yüksek",
      "preconditions": "The OBU is in the process of terminating the communication session and has been repeating the termination message.",
      "test_inputs": "No acknowledgement is received after the last allowed repetition.",
      "assumptions": "The defined number of repetitions is as per SUBSET-026 Appendix A.3.1.",
      "steps": [
        {
          "no": 1,
          "action": "The OBU sends the 'Termination of Communication Session' message for the defined maximum number of times.",
          "expected": "The message is sent the last time."
        },
        {
          "no": 2,
          "action": "Wait for the fixed waiting time after the last sending without receiving an acknowledgement.",
          "expected": "The OBU considers the communication session terminated."
        }
      ]
    }
  ]
}

{
  "test_cases": [
    {
      "id": "TC-045-01",
      "title": "Driver requests display of estimated front end position",
      "covers": [
        "ETC-045"
      ],
      "type": "Normal",
      "priority": "Yüksek",
      "preconditions": "The OBU is in operational mode and the train is moving.",
      "test_inputs": "Driver command: 'Show Position'",
      "assumptions": "",
      "steps": [
        {
          "no": 1,
          "action": "The driver issues the request to display the geographical position of the train's estimated front end.",
          "expected": "The OBU displays the geographical position in relation to the track kilometre."
        }
      ]
    },
    {
      "id": "TC-045-02",
      "title": "Driver requests to stop display of estimated front end position",
      "covers": [
        "ETC-045"
      ],
      "type": "Normal",
      "priority": "Yüksek",
      "preconditions": "The OBU is currently displaying the geographical position of the train's estimated front end.",
      "test_inputs": "Driver command: 'Hide Position'",
      "assumptions": "",
      "steps": [
        {
          "no": 1,
          "action": "The driver issues the request to stop the display of the geographical position.",
          "expected": "The OBU stops displaying the geographical position of the train's estimated front end."
        }
      ]
    },
    {
      "id": "TC-045-03",
      "title": "No display of position without driver request",
      "covers": [
        "ETC-045"
      ],
      "type": "Normal",
      "priority": "Orta",
      "preconditions": "The OBU is in operational mode and the train is moving. The position display is not active.",
      "test_inputs": "None",
      "assumptions": "",
      "steps": [
        {
          "no": 1,
          "action": "Wait for a defined period without issuing any driver request for position display.",
          "expected": "The OBU does not display the geographical position of the train's estimated front end."
        }
      ]
    },
    {
      "id": "TC-046-01",
      "title": "Position calculation includes distance travelled since reference",
      "covers": [
        "ETC-046"
      ],
      "type": "Normal",
      "priority": "Yüksek",
      "preconditions": "The OBU has a known geographical reference location (e.g., Track Km 10.000). The train has travelled a known distance (e.g., 500 meters) since this reference.",
      "test_inputs": "Distance travelled since reference: 500m",
      "assumptions": "The OBU's internal odometry or distance calculation is accurate for the test segment.",
      "steps": [
        {
          "no": 1,
          "action": "The driver requests the display of the geographical position.",
          "expected": "The OBU displays a position that is the reference location plus the distance travelled (e.g., Track Km 10.500)."
        }
      ]
    },
    {
      "id": "TC-046-02",
      "title": "Position calculation at zero distance since reference",
      "covers": [
        "ETC-046"
      ],
      "type": "Sınır",
      "priority": "Orta",
      "preconditions": "The OBU is located exactly at the geographical reference location (distance travelled since reference is 0).",
      "test_inputs": "Distance travelled since reference: 0m",
      "assumptions": "",
      "steps": [
        {
          "no": 1,
          "action": "The driver requests the display of the geographical position.",
          "expected": "The OBU displays the geographical position equal to the reference location."
        }
      ]
    }
  ]
}

{
  "test_cases": [
    {
      "id": "TC-ETC-050-01",
      "title": "MA uzunluğunu tam kapsamayan SSP/gradient ile MA kabul edilmemesi",
      "covers": [
        "ETC-050"
      ],
      "type": "Hata",
      "priority": "Yüksek",
      "preconditions": "OBU, MA işleme modundadır. Araçta mevcut SSP ve gradient verileri, gelen MA'nın tam uzunluğunu kapsamayacak şekilde yapılandırılmıştır.",
      "test_inputs": "Gelen MA mesajı, araçta mevcut SSP/gradient verilerinin kapsamından daha uzun bir mesafe içerir.",
      "assumptions": "MA'nın tam uzunluğu SUBSET-026 §3.7.2.3.1–3.7.2.3.2'ye göre hesaplanmaktadır.",
      "steps": [
        {
          "no": 1,
          "action": "Araçta mevcut SSP ve gradient verilerinin MA'nın tam uzunluğunu kapsamadığı bir MA mesajı OBU'ya gönderilir.",
          "expected": "OBU, MA'yı ve ilişkili mod profillerini kabul etmez."
        },
        {
          "no": 2,
          "action": "OBU'nun MA kabul durumu kontrol edilir.",
          "expected": "MA reddedilir ve ilgili hata durumu veya uyarı üretilir."
        }
      ]
    },
    {
      "id": "TC-ETC-050-02",
      "title": "MA ile birlikte gelen SSP/gradient verilerinin MA uzunluğunu tam kapsamaması",
      "covers": [
        "ETC-050"
      ],
      "type": "Hata",
      "priority": "Yüksek",
      "preconditions": "OBU, MA işleme modundadır. Araçta mevcut SSP/gradient verileri yoktur veya MA ile birlikte gelen SSP/gradient verileri MA'nın tam uzunluğunu kapsamayacak şekilde tanımlanmıştır.",
      "test_inputs": "MA mesajı, kendisiyle birlikte gelen SSP ve gradient verilerinin MA'nın tam uzunluğunu kapsamadığı bir senaryoda gönderilir.",
      "assumptions": "MA ile birlikte gelen SSP/gradient verileri, MA'nın başlangıcından bitişine kadar olan mesafeyi tam olarak kapsamamaktadır.",
      "steps": [
        {
          "no": 1,
          "action": "MA ile birlikte, MA'nın tam uzunluğunu kapsamayan SSP ve gradient verileri OBU'ya gönderilir.",
          "expected": "OBU, MA'yı ve ilişkili mod profillerini kabul etmez."
        },
        {
          "no": 2,
          "action": "OBU'nun MA kabul durumu kontrol edilir.",
          "expected": "MA reddedilir ve ilgili hata durumu veya uyarı üretilir."
        }
      ]
    },
    {
      "id": "TC-ETC-050-03",
      "title": "MA uzunluğunu tam kapsayan SSP/gradient ile MA kabul edilmesi (Negatif Kontrol)",
      "covers": [
        "ETC-050"
      ],
      "type": "Normal",
      "priority": "Orta",
      "preconditions": "OBU, MA işleme modundadır. Araçta mevcut SSP ve gradient verileri, gelen MA'nın tam uzunluğunu tam olarak kapsamaktadır.",
      "test_inputs": "Gelen MA mesajı, araçta mevcut SSP/gradient verilerinin tam olarak kapsadığı bir mesafe içerir.",
      "assumptions": "MA'nın tam uzunluğu SUBSET-026 §3.7.2.3.1–3.7.2.3.2'ye göre hesaplanmaktadır ve SSP/gradient verileri bu uzunluğu tam olarak kapsamaktadır.",
      "steps": [
        {
          "no": 1,
          "action": "Araçta mevcut SSP ve gradient verilerinin MA'nın tam uzunluğunu tam olarak kapsadığı bir MA mesajı OBU'ya gönderilir.",
          "expected": "OBU, MA'yı ve ilişkili mod profillerini kabul eder."
        },
        {
          "no": 2,
          "action": "OBU'nun MA kabul durumu kontrol edilir.",
          "expected": "MA kabul edilir ve ilgili mod profilleri etkinleştirilir."
        }
      ]
    }
  ]
}

{
  "test_cases": [
    {
      "id": "TC-01",
      "title": "Safe radio connection loss triggers immediate reconnection attempt",
      "covers": [
        "ETC-010"
      ],
      "type": "Normal",
      "priority": "Yüksek",
      "preconditions": "OBU is in operational mode. A safe radio connection is established with a specific radio system (e.g., GSM-R). EURORADIO is active.",
      "test_inputs": "Simulated loss of safe radio connection signal from EURORADIO.",
      "assumptions": "The radio system previously used for the successful connection is available and functional.",
      "steps": [
        {
          "no": 1,
          "action": "Establish a safe radio connection between OBU and the radio system.",
          "expected": "OBU status indicates an active safe radio connection."
        },
        {
          "no": 2,
          "action": "Simulate the loss of the safe radio connection via EURORADIO.",
          "expected": "OBU immediately initiates an attempt to set up a new safe radio connection with the same radio system."
        }
      ]
    },
    {
      "id": "TC-02",
      "title": "Repeated reconnection attempts until success",
      "covers": [
        "ETC-011"
      ],
      "type": "Normal",
      "priority": "Yüksek",
      "preconditions": "OBU is in operational mode. A communication session is established. Safe radio connection is lost.",
      "test_inputs": "Simulated radio interference preventing reconnection for a short duration, followed by restoration of radio availability.",
      "assumptions": "The communication session is not terminated and the train has not passed the RIU termination location.",
      "steps": [
        {
          "no": 1,
          "action": "Cause the loss of the safe radio connection during an active session.",
          "expected": "OBU starts repeating attempts to set up a new safe radio connection."
        },
        {
          "no": 2,
          "action": "Keep the radio system unavailable for a defined period (e.g., 10 seconds) to force failed reconnection attempts.",
          "expected": "OBU continues to repeat reconnection attempts without stopping."
        },
        {
          "no": 3,
          "action": "Restore radio system availability.",
          "expected": "OBU successfully establishes a new safe radio connection and stops repeating attempts."
        }
      ]
    },
    {
      "id": "TC-03",
      "title": "Reconnection attempts stop when session is terminated",
      "covers": [
        "ETC-011"
      ],
      "type": "Normal",
      "priority": "Orta",
      "preconditions": "OBU is in operational mode. A communication session is established. Safe radio connection is lost.",
      "test_inputs": "Command to terminate the communication session.",
      "assumptions": "The train has not passed the RIU termination location.",
      "steps": [
        {
          "no": 1,
          "action": "Cause the loss of the safe radio connection during an active session.",
          "expected": "OBU starts repeating attempts to set up a new safe radio connection."
        },
        {
          "no": 2,
          "action": "Issue a command to terminate the communication session.",
          "expected": "OBU stops repeating reconnection attempts and regards the session as terminated."
        }
      ]
    },
    {
      "id": "TC-04",
      "title": "Reconnection attempts stop when train passes RIU termination location",
      "covers": [
        "ETC-011"
      ],
      "type": "Normal",
      "priority": "Orta",
      "preconditions": "OBU is in operational mode. A communication session is established with an RIU order specifying a termination location. Safe radio connection is lost.",
      "test_inputs": "Train movement data simulating passage of the RIU termination location.",
      "assumptions": "The communication session is not otherwise terminated.",
      "steps": [
        {
          "no": 1,
          "action": "Cause the loss of the safe radio connection during an active session.",
          "expected": "OBU starts repeating attempts to set up a new safe radio connection."
        },
        {
          "no": 2,
          "action": "Simulate the train passing the location given in the RIU order to terminate the communication session.",
          "expected": "OBU stops repeating reconnection attempts."
        }
      ]
    }
  ]
}

{
  "test_cases": [
    {
      "id": "TC-01",
      "title": "Güç açıldığında GSM-R kayıt talebinin gönderilmesi",
      "covers": [
        "ETC-015"
      ],
      "type": "Normal",
      "priority": "Yüksek",
      "preconditions": "OBU kapalı durumdadır. GSM-R Mobil Terminal bağlıdır ve çalışır durumdadır.",
      "test_inputs": "",
      "assumptions": "GSM-R ağının mevcut olduğu varsayılır.",
      "steps": [
        {
          "no": 1,
          "action": "OBU güç açma komutu verilir.",
          "expected": "OBU, bağlı GSM-R Mobil Terminal(ler) için GSM-R Radyo Ağına kayıt talebi gönderir."
        }
      ]
    },
    {
      "id": "TC-02",
      "title": "Sürücü yeni GSM-R Radyo Ağı kimliği girdiğinde kayıt talebinin gönderilmesi",
      "covers": [
        "ETC-015"
      ],
      "type": "Normal",
      "priority": "Yüksek",
      "preconditions": "OBU çalışır durumdadır. GSM-R Mobil Terminal bağlıdır. Mevcut kayıt farklı bir ağ kimliği içindir.",
      "test_inputs": "Yeni GSM-R Radyo Ağı kimliği (PLMN ID).",
      "assumptions": "",
      "steps": [
        {
          "no": 1,
          "action": "Sürücü arayüzünden yeni bir GSM-R Radyo Ağı kimliği girilir.",
          "expected": "OBU, yeni kimlik için GSM-R Radyo Ağına kayıt talebi gönderir."
        }
      ]
    },
    {
      "id": "TC-03",
      "title": "Ray kenarı komutuyla GSM-R kayıt talebinin gönderilmesi",
      "covers": [
        "ETC-015"
      ],
      "type": "Normal",
      "priority": "Yüksek",
      "preconditions": "OBU çalışır durumdadır. GSM-R Mobil Terminal bağlıdır.",
      "test_inputs": "Ray kenarından gelen kayıt komutu mesajı.",
      "assumptions": "",
      "steps": [
        {
          "no": 1,
          "action": "Ray kenarından GSM-R kayıt komutu gönderilir.",
          "expected": "OBU, bağlı GSM-R Mobil Terminal(ler) için GSM-R Radyo Ağına kayıt talebi gönderir."
        }
      ]
    },
    {
      "id": "TC-04",
      "title": "Radyo Ağı tipi hatırlanmadığında varsayılan tipin kullanılması",
      "covers": [
        "ETC-016"
      ],
      "type": "Normal",
      "priority": "Yüksek",
      "preconditions": "OBU'da hatırlanmış Radyo Ağı tipi yoktur (ilk güç açma veya Sistem Arızası sonrası). Varsayılan Radyo Ağı tipi yapılandırılmıştır.",
      "test_inputs": "",
      "assumptions": "Varsayılan Radyo Ağı tipi 'GSM-R' olarak yapılandırılmıştır.",
      "steps": [
        {
          "no": 1,
          "action": "OBU güç açılır ve Radyo Ağı tipi sorgulanır.",
          "expected": "OBU, yapılandırılmış varsayılan Radyo Ağı tipini kullanır."
        }
      ]
    },
    {
      "id": "TC-05",
      "title": "Gerekli radyo sistemi kayıtlı değilken RBC oturumu için güvenli bağlantı talebinin gönderilmemesi",
      "covers": [
        "ETC-017"
      ],
      "type": "Hata",
      "priority": "Yüksek",
      "preconditions": "OBU çalışır durumdadır. Depolanan Radyo Ağı tipi gerektirdiği radyo sistemi (ör. GSM-R) kayıtlı değildir.",
      "test_inputs": "Ray kenarından gelen RBC oturumu kurma komutu.",
      "assumptions": "GSM-R terminali kayıtlı değildir.",
      "steps": [
        {
          "no": 1,
          "action": "Ray kenarından RBC ile oturum kurma komutu gönderilir.",
          "expected": "OBU, güvenli radyo bağlantısı kurulumu talebinde bulunmaz."
        }
      ]
    },
    {
      "id": "TC-06",
      "title": "GSM-R terminali kayıtlı değilken RIU oturumu için güvenli bağlantı talebinin gönderilmemesi",
      "covers": [
        "ETC-018"
      ],
      "type": "Hata",
      "priority": "Yüksek",
      "preconditions": "OBU çalışır durumdadır. Hiçbir GSM-R Mobil Terminal, bir GSM-R Radyo Ağına düzgün şekilde kayıtlı değildir.",
      "test_inputs": "Ray kenarından gelen RIU ile iletişim oturumu kurma komutu.",
      "assumptions": "",
      "steps": [
        {
          "no": 1,
          "action": "Ray kenarından RIU ile iletişim oturumu kurma komutu gönderilir.",
          "expected": "OBU, güvenli radyo bağlantısı kurulumu talebinde bulunmaz."
        }
      ]
    }
  ]
}

{
  "test_cases": [
    {
      "id": "TC-055-01",
      "title": "MA request includes all applicable reasons",
      "covers": [
        "ETC-055"
      ],
      "type": "Normal",
      "priority": "Yüksek",
      "preconditions": "OBU is in Level 2 and connected to RBC. Multiple MA request conditions are active simultaneously (e.g., Section timer expired and track description deletion).",
      "test_inputs": "Simulate conditions that trigger multiple MA request reasons as defined in SUBSET-026 §3.8.2.1.1.",
      "assumptions": "The RBC or a test tool can capture and decode the MA request message to verify the content of the 'MA request reasons' field.",
      "steps": [
        {
          "no": 1,
          "action": "Trigger a condition that results in a single MA request reason (e.g., Section timer expiry).",
          "expected": "OBU sends an MA request to the RBC. The message contains only that specific reason."
        },
        {
          "no": 2,
          "action": "Trigger a second condition that results in a different MA request reason while the first condition is still relevant or just before the next request.",
          "expected": "OBU sends an MA request to the RBC. The message contains both applicable reasons."
        }
      ]
    },
    {
      "id": "TC-056-01",
      "title": "MA request triggered by perturbation-location criterion",
      "covers": [
        "ETC-056"
      ],
      "type": "Normal",
      "priority": "Yüksek",
      "preconditions": "OBU is in Level 2. The train is moving. The perturbation-location criterion is configured and active.",
      "test_inputs": "Train speed and position data such that the train front crosses the calculated perturbation location.",
      "assumptions": "The perturbation location is calculated based on the current train speed and acceleration/deceleration profile as per SUBSET-026 §3.8.2.2.1.",
      "steps": [
        {
          "no": 1,
          "action": "Move the train front to a position just before the calculated perturbation location.",
          "expected": "No MA request is sent to the RBC."
        },
        {
          "no": 2,
          "action": "Move the train front so that it passes the calculated perturbation location.",
          "expected": "OBU triggers and sends an MA request to the RBC."
        }
      ]
    },
    {
      "id": "TC-056-02",
      "title": "MA request triggered by Section timer/LOA speed timer criterion",
      "covers": [
        "ETC-056"
      ],
      "type": "Normal",
      "priority": "Yüksek",
      "preconditions": "OBU is in Level 2. The Section timer or LOA speed timer is running.",
      "test_inputs": "Time progression to reach the timer limit defined by the criterion.",
      "assumptions": "The timer value is set to a short duration for testing purposes to avoid long wait times.",
      "steps": [
        {
          "no": 1,
          "action": "Wait until the time resulting from the Section timer/LOA speed timer criterion is reached.",
          "expected": "OBU triggers and sends an MA request to the RBC."
        }
      ]
    },
    {
      "id": "TC-057-01",
      "title": "MA request on track description deletion (valid situation)",
      "covers": [
        "ETC-057"
      ],
      "type": "Normal",
      "priority": "Yüksek",
      "preconditions": "OBU is in Level 2. A track description is currently stored in the OBU.",
      "test_inputs": "RBC sends a message deleting a part of the track description under a situation defined in SUBSET-026 Appendix A.3.4, excluding situations a, b, f, and k (e.g., situation c).",
      "assumptions": "The specific situation chosen (e.g., c) is one that requires an MA request according to the requirement.",
      "steps": [
        {
          "no": 1,
          "action": "Receive a track description deletion message from the RBC corresponding to a valid situation (not a, b, f, or k).",
          "expected": "OBU sends an MA request to the RBC."
        }
      ]
    },
    {
      "id": "TC-057-02",
      "title": "No MA request on track description deletion (excluded situations)",
      "covers": [
        "ETC-057"
      ],
      "type": "Hata",
      "priority": "Orta",
      "preconditions": "OBU is in Level 2. A track description is currently stored in the OBU.",
      "test_inputs": "RBC sends a message deleting a part of the track description under one of the excluded situations: a, b, f, or k.",
      "assumptions": "The test verifies that the OBU does NOT send an MA request for these specific excluded cases, ensuring compliance with the exception clause.",
      "steps": [
        {
          "no": 1,
          "action": "Receive a track description deletion message from the RBC corresponding to situation 'a' (or b, f, or k).",
          "expected": "OBU does NOT send an MA request to the RBC."
        }
      ]
    }
  ]
}

{
  "test_cases": [
    {
      "id": "TC-ETC-026-01",
      "title": "Report train position to RBC referring to last passed compliant LRBG",
      "covers": [
        "ETC-026"
      ],
      "type": "Normal",
      "priority": "Yüksek",
      "preconditions": "OBU is in operational mode. A compliant LRBG (e.g., LRBG-100) has been passed. The OBU has reported its position to the RBC.",
      "test_inputs": "Train moves forward. Next LRBG (LRBG-101) is passed.",
      "assumptions": "LRBG-100 is compliant with SUBSET-026 §3.6.5.1.8. Linking consistency is not checked or LRBG-100 is not marked as unlinked.",
      "steps": [
        {
          "no": 1,
          "action": "Observe the OBU's position report to the RBC after passing LRBG-100.",
          "expected": "The OBU reports the train position to the RBC referring to LRBG-100."
        },
        {
