      "id": "TC-ETC-006-01",
      "title": "Memorization of successful radio system for session establishment",
      "covers": [
        "ETC-006"
      ],
      "type": "Normal",
      "priority": "Yüksek",
      "preconditions": "The OBU is equipped with both GSM-R and FRMCS radio systems. A communication session is successfully established using the FRMCS radio system.",
      "test_inputs": "Successful session establishment via FRMCS.",
      "assumptions": "The OBU has a mechanism to store the last successfully used radio system.",
      "steps": [
