{
  "test_cases": [
    {
      "id": "TC-001",
      "title": "Failed sign-in response consistency for existing and non-existing users",
      "covers": [
        "KDH-055"
      ],
      "type": "Normal",
      "priority": "Yüksek",
      "preconditions": "A valid user account exists in the system. A non-existing user identifier is known.",
      "test_inputs": "Valid user ID, invalid password; Non-existing user ID, invalid password.",
      "assumptions": "The system allows sign-in attempts with any user identifier format.",
      "steps": [
        {
          "no": 1,
          "action": "Attempt sign-in with a valid user ID and an incorrect password.",
          "expected": "The system returns a generic error message (e.g., 'Invalid credentials') and an HTTP status code (e.g., 401 or 200 with error body)."
        },
        {
          "no": 2,
          "action": "Attempt sign-in with a non-existing user ID and an incorrect password.",
          "expected": "The system returns the exact same generic error message and HTTP status code as in step 1."
        },
        {
          "no": 3,
          "action": "Measure the response time for the sign-in attempt with the valid user ID.",
          "expected": "The response time is within the same statistical range as the response time for the non-existing user ID (no significant delay indicating user existence)."
        }
      ]
    },
    {
      "id": "TC-002",
      "title": "Failed registration response consistency for existing and non-existing users",
      "covers": [
        "KDH-055"
      ],
      "type": "Normal",
      "priority": "Yüksek",
      "preconditions": "A valid user account exists in the system. A non-existing user identifier is known.",
      "test_inputs": "Valid user ID, valid registration data; Non-existing user ID, valid registration data.",
      "assumptions": "The registration process validates user uniqueness.",
      "steps": [
        {
          "no": 1,
          "action": "Attempt registration with a user ID that already exists in the system.",
          "expected": "The system returns a generic error message (e.g., 'Registration failed') and an HTTP status code."
        },
        {
          "no": 2,
          "action": "Attempt registration with a user ID that does not exist in the system.",
          "expected": "The system returns the exact same generic error message and HTTP status code as in step 1, or a success message that does not reveal the previous state of the user ID in a way that distinguishes it from a failed attempt if the requirement implies uniform failure responses. *Correction based on OWASP V6.3.8*: Typically, registration success is distinct, but the *failure* to register due to existing user must not be distinguishable from other failures if it reveals existence. However, V6.3.8 specifically targets *failed* responses. If registration succeeds for new users, that is expected. The test focuses on the *failure* case. Let's refine: The requirement says 'prevent valid users from being deduced from... failed... responses'. So we compare a failed registration (existing user) with another failed registration (e.g., invalid email format) or ensure the 'user exists' error is not distinct. Let's assume the system returns a generic 'Registration unsuccessful' for both existing user and invalid data."
        },
        {
          "no": 3,
          "action": "Compare the error message and HTTP code from step 1 with a registration attempt that fails for a different reason (e.g., invalid email format).",
          "expected": "The error message and HTTP status code are identical, preventing deduction of user existence."
        }
      ]
    },
    {
      "id": "TC-003",
      "title": "Failed forgotten-password response consistency for existing and non-existing users",
      "covers": [
        "KDH-055"
      ],
