      "preconditions": "A valid user account exists in the system. A non-existing user identifier is known.",
      "test_inputs": "Valid user ID; Non-existing user ID.",
      "assumptions": "The system sends a confirmation message regardless of user existence to prevent enumeration.",
      "steps": [
        {
          "no": 1,
          "action": "Initiate the forgotten-password process with a valid user ID.",
          "expected": "The system displays a generic success message (e.g., 'If an account exists, a reset link has been sent') and returns an HTTP 200 status."
        },
        {
          "no": 2,
          "action": "Initiate the forgotten-password process with a non-existing user ID.",
          "expected": "The system displays the exact same generic success message and returns the same HTTP 200 status."
        },
        {
          "no": 3,
          "action": "Check the response time for both requests.",
          "expected": "The response times are statistically similar, with no significant delay for the existing user."
        }
      ]
